/**
 * EmptyState. A quiet recess — the screen is on and
 * working, there is simply nothing in it yet. Composes var(--echo-*).
 */
.echo-empty-state {
  display: grid;
  /* The column can shrink; without it the longest line sets the width and the
     card pushes its container open at narrow widths. */
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: var(--echo-space-4);
  padding: var(--echo-space-11) var(--echo-space-10);
  border-radius: var(--echo-radius-xl);
  text-align: center;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow:
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.04 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-empty-state__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--echo-space-1);
  color: var(--echo-text-dim);
  opacity: 0.7;
}

.echo-empty-state__icon svg {
  width: var(--echo-icon-xl, 28px);
  height: var(--echo-icon-xl, 28px);
}

/* An illustration keeps its own size and colour. */
.echo-empty-state__illustration {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-inline-size: 100%;
  margin-bottom: var(--echo-space-3);
}

.echo-empty-state__title {
  margin: 0;
  font-size: var(--echo-text-md);
  font-weight: var(--echo-weight-bold, 700);
  line-height: var(--echo-leading-snug, 1.4);
  color: var(--echo-text);
}

.echo-empty-state__description {
  margin: 0;
  max-width: 42ch;
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}

.echo-empty-state__action {
  margin-top: var(--echo-space-5);
}

/**
 * EmptyState — nothing here, and what to do about it.
 *
 * The useful distinction the component enforces by shape: an empty state is
 * a TITLE plus a WAY FORWARD. A title alone is a dead end, which is why the
 * action slot sits in the API rather than being left to the caller's layout.
 *
 * Static; consumes only var(--echo-*) via empty-state.css.
 */
import type { HTMLAttributes, ReactNode } from "react";
import "./empty-state.css";

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  title: string;
  description?: ReactNode;
  /** Decorative mark above the title: a small line icon, drawn quiet. */
  icon?: ReactNode;
  /**
   * A picture above the title at its own size, in full colour: a Creature, an
   * illustration. Takes the icon's place when both are given.
   */
  illustration?: ReactNode;
  /** The way forward — usually one HardwareButton. */
  action?: ReactNode;
}

export function EmptyState({
  title,
  description,
  icon,
  illustration,
  action,
  className,
  ...rest
}: EmptyStateProps) {
  return (
    <div className={["echo-empty-state", className].filter(Boolean).join(" ")} {...rest}>
      {illustration ? (
        <div className="echo-empty-state__illustration" aria-hidden="true">
          {illustration}
        </div>
      ) : icon ? (
        <div className="echo-empty-state__icon" aria-hidden="true">
          {icon}
        </div>
      ) : null}
      <p className="echo-empty-state__title">{title}</p>
      {description ? <p className="echo-empty-state__description">{description}</p> : null}
      {action ? <div className="echo-empty-state__action">{action}</div> : null}
    </div>
  );
}
